style.css:
@-moz-document domain("google.com"), domain("google.ru") {
/* Скрываем стандартный логотип Google */
    img[alt="Google"], .lnXgbe, .k1zDcd {
        opacity: 0 !important;
    }

    /* Подставляем аниме-логотип на главной странице */
    .k1zDcd, .lnXgbe {
        background-image: url("https://postimg.co") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        opacity: 1 !important;
    }

    /* Подставляем аниме-логотип на странице выдачи (вверху слева) */
    .logo img, a#logo img, .JF1Ygd img {
        content: url("https://postimg.co") !important;
        object-fit: contain !important;
    }
}
